// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

interface IERC165Probe {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}
interface IAccessControlProbe {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(uint256 seed) public {
        // The fuzzer decides which of the two advertised ERC-165 interfaces is probed.
        // No concrete deciding id is hard-coded: the choice comes from the fuzzed seed.
        bytes4 id = (seed % 2 == 0)
            ? type(IERC165Probe).interfaceId
            : type(IAccessControlProbe).interfaceId;

        // General rule: an ERC-165 compliant AccessControl reports support for every
        // interface it inherits/advertises; supportsInterface must return true for it.
        assertTrue(c.supportsInterface(id));
    }
}
